-- Triangle Resells CRM: the whole database setup in one file (generated by `npm run bundle-sql`; don't edit by hand).
-- 9 migrations: 0001_core.sql, 0002_bookings.sql, 0003_bot_sync.sql, 0004_stock.sql, 0005_reports.sql, 0006_restocks.sql, 0007_assistant.sql, 0008_phase5.sql, 0009_test_cleanup.sql. Safe to run again.

-- ===================== 0001_core.sql =====================
-- Triangle Resells CRM v1, phase 1: team, customers, activity log, undo.
-- Every write goes through a function below, so the change and its activity-log line happen in ONE transaction:
-- if anything fails, nothing is half-saved.
--
-- Who did it ("actor"):
--   * Josh / Chema / Diego logged in to the CRM: taken from their Supabase login (auth.uid() -> team_members).
--   * The bot (and server scripts) call with the service-role key and pass p_actor ('Bot', 'System'...).
--     Only the service role may name an actor; a logged-in person can never pretend to be someone else.

-- ---------- team ----------
create table if not exists team_members (
  id uuid primary key default gen_random_uuid(),
  user_id uuid unique,               -- the person's Supabase login (auth.users.id), linked once they sign up
  name text not null unique check (name in ('Josh', 'Chema', 'Diego')),
  email text unique,
  created_at timestamptz not null default now()
);
insert into team_members (name) values ('Josh'), ('Chema'), ('Diego') on conflict (name) do nothing;

-- ---------- customers ----------
create table if not exists customers (
  id uuid primary key default gen_random_uuid(),
  ig_user_id text unique,            -- Instagram's id for the buyer (what the bot sees)
  ig_handle text,                    -- stored without "@", lowercase
  name text,
  phone text,
  dm_conversations integer not null default 0,
  notes text,
  is_test boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create unique index if not exists customers_ig_handle_key on customers (ig_handle) where ig_handle is not null;
create index if not exists customers_phone_idx on customers (phone) where phone is not null;

-- ---------- activity log ----------
create table if not exists activity_log (
  id bigserial primary key,
  at timestamptz not null default now(),
  actor text not null,               -- Josh / Chema / Diego / Bot / System
  action text not null check (action in ('create', 'update', 'delete')),
  entity text not null,              -- table name, e.g. customers, bookings
  entity_id text,
  summary text,                      -- short human line, e.g. "Bot rescheduled TEST buyer to 11/20/2026"
  before jsonb,
  after jsonb,
  changes jsonb,                     -- {field: {from, to}} for updates
  undo_of bigint references activity_log (id),
  is_test boolean not null default false
);
create index if not exists activity_log_at_idx on activity_log (at desc);
create index if not exists activity_log_entity_idx on activity_log (entity, entity_id);

-- ---------- who is acting ----------
create or replace function crm_actor() returns text
language plpgsql stable security definer set search_path = public as $$
declare a text;
begin
  a := nullif(current_setting('crm.actor', true), '');
  if a is not null then return a; end if;
  select name into a from team_members where user_id = auth.uid();
  return coalesce(a, 'System');
end $$;

-- Called at the start of every write function. Only the service role (bot / server) may name the actor.
create or replace function crm_begin(p_actor text, p_summary text default null) returns text
language plpgsql security definer set search_path = public as $$
declare a text;
begin
  if coalesce(auth.role(), '') = 'service_role' and p_actor is not null then
    if p_actor not in ('Bot', 'System', 'Josh', 'Chema', 'Diego') then
      raise exception 'unknown actor %', p_actor using errcode = '22023';
    end if;
    perform set_config('crm.actor', p_actor, true);
  else
    -- A logged-in person: must be on the team.
    if not exists (select 1 from team_members where user_id = auth.uid()) then
      raise exception 'not a team member' using errcode = '42501';
    end if;
    perform set_config('crm.actor', '', true);
  end if;
  perform set_config('crm.summary', coalesce(p_summary, ''), true);
  a := crm_actor();
  return a;
end $$;

-- Generic trigger: one activity-log line per insert / update / delete, with before, after and the changed fields.
create or replace function crm_log_change() returns trigger
language plpgsql security definer set search_path = public as $$
declare o jsonb; n jsonb; ch jsonb;
begin
  if tg_op = 'INSERT' then
    n := to_jsonb(new);
  elsif tg_op = 'UPDATE' then
    o := to_jsonb(old); n := to_jsonb(new);
    select jsonb_object_agg(key, jsonb_build_object('from', o -> key, 'to', value)) into ch
      from jsonb_each(n) where key <> 'updated_at' and (o -> key) is distinct from value;
    if ch is null then return new; end if;     -- nothing really changed: no log line
  else
    o := to_jsonb(old);
  end if;
  insert into activity_log (actor, action, entity, entity_id, summary, before, after, changes, undo_of, is_test)
  values (
    crm_actor(), case tg_op when 'INSERT' then 'create' when 'UPDATE' then 'update' else 'delete' end, tg_table_name, coalesce(n ->> 'id', o ->> 'id'),
    nullif(current_setting('crm.summary', true), ''), o, n, ch,
    nullif(current_setting('crm.undo_of', true), '')::bigint,
    coalesce((coalesce(n, o) ->> 'is_test')::boolean, false)
  );
  return coalesce(new, old);
end $$;

create or replace function crm_touch() returns trigger language plpgsql as $$
begin new.updated_at := now(); return new; end $$;

drop trigger if exists customers_log on customers;
create trigger customers_log after insert or update or delete on customers for each row execute function crm_log_change();
drop trigger if exists customers_touch on customers;
create trigger customers_touch before update on customers for each row execute function crm_touch();

-- ---------- customers API ----------
create or replace function crm_norm_handle(h text) returns text language sql immutable as $$
  select nullif(lower(regexp_replace(trim(coalesce(h, '')), '^@+', '')), '')
$$;

-- Find a customer by Instagram id, then handle, then phone. Returns null when unknown.
create or replace function find_customer(p_ig_user_id text default null, p_ig_handle text default null, p_phone text default null)
returns jsonb language sql stable security definer set search_path = public as $$
  select to_jsonb(c) from customers c
  where (p_ig_user_id is not null and c.ig_user_id = p_ig_user_id)
     or (crm_norm_handle(p_ig_handle) is not null and c.ig_handle = crm_norm_handle(p_ig_handle))
     or (nullif(trim(p_phone), '') is not null and c.phone = trim(p_phone))
  order by (c.ig_user_id = p_ig_user_id) desc nulls last, (c.ig_handle = crm_norm_handle(p_ig_handle)) desc nulls last
  limit 1
$$;

-- Create the customer, or fill in what's new on the existing one. Never blanks out a field that's already set.
create or replace function upsert_customer(p jsonb, p_actor text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare found jsonb; c customers; h text := crm_norm_handle(p ->> 'ig_handle');
begin
  perform crm_begin(p_actor);
  found := find_customer(p ->> 'ig_user_id', h, p ->> 'phone');
  if found is null then
    insert into customers (ig_user_id, ig_handle, name, phone, notes, is_test)
    values (nullif(p ->> 'ig_user_id', ''), h, nullif(trim(p ->> 'name'), ''), nullif(trim(p ->> 'phone'), ''),
            nullif(trim(p ->> 'notes'), ''), coalesce((p ->> 'is_test')::boolean, false))
    returning * into c;
  else
    update customers set
      ig_user_id = coalesce(ig_user_id, nullif(p ->> 'ig_user_id', '')),
      ig_handle  = coalesce(h, ig_handle),
      name       = coalesce(nullif(trim(p ->> 'name'), ''), name),
      phone      = coalesce(nullif(trim(p ->> 'phone'), ''), phone),
      notes      = coalesce(nullif(trim(p ->> 'notes'), ''), notes)
    where id = (found ->> 'id')::uuid
    returning * into c;
  end if;
  return to_jsonb(c);
end $$;

-- ---------- undo ----------
-- Reverses one activity-log line: a create is deleted, a delete is put back, an update is set back to "before".
-- The undo is itself logged (undo_of = the line it reversed). Only tables listed here can be undone.
create or replace function undo_activity(p_id bigint, p_actor text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare l activity_log; cols text;
begin
  select * into l from activity_log where id = p_id;
  if l is null then raise exception 'no activity %', p_id using errcode = 'P0002'; end if;
  if not (l.entity = any (crm_undoable())) then
    raise exception 'cannot undo changes to %', l.entity using errcode = '22023';
  end if;
  if exists (select 1 from activity_log where undo_of = p_id) then
    raise exception 'activity % was already undone', p_id using errcode = '22023';
  end if;
  perform crm_begin(p_actor, 'Undo of #' || p_id);
  perform set_config('crm.undo_of', p_id::text, true);
  if l.action = 'create' then
    execute format('delete from %I where id = $1::uuid', l.entity) using l.entity_id;
  elsif l.action = 'delete' then
    execute format('insert into %I select * from jsonb_populate_record(null::%I, $1)', l.entity, l.entity) using l.before;
  else
    select string_agg(format('%I = r.%I', key, key), ', ') into cols
      from jsonb_object_keys(l.changes) key;
    execute format('update %I t set %s from jsonb_populate_record(null::%I, $1) r where t.id = $2::uuid', l.entity, cols, l.entity)
      using l.before, l.entity_id;
  end if;
  perform set_config('crm.undo_of', '', true);
  return (select to_jsonb(a) from activity_log a where undo_of = p_id order by id desc limit 1);
end $$;

-- Later phases add their tables here (bookings, booking_items, ...).
create or replace function crm_undoable() returns text[] language sql immutable as $$ select array['customers'] $$;

create or replace function recent_activity(p_limit integer default 50, p_entity text default null, p_entity_id text default null)
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(to_jsonb(a) order by a.id desc), '[]'::jsonb) from (
    select * from activity_log
    where (p_entity is null or entity = p_entity) and (p_entity_id is null or entity_id = p_entity_id)
    order by id desc limit least(greatest(p_limit, 1), 500)
  ) a
$$;

-- ---------- access ----------
-- Row level security: only the three team members (logged in) can read; writes only through the functions above.
-- The bot uses the service-role key on the server, which bypasses RLS; it never reaches the browser.
alter table team_members enable row level security;
alter table customers enable row level security;
alter table activity_log enable row level security;

create or replace function is_team() returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from team_members where user_id = auth.uid())
$$;

drop policy if exists team_read on team_members;
create policy team_read on team_members for select to authenticated using (is_team());
drop policy if exists team_read on customers;
create policy team_read on customers for select to authenticated using (is_team());
drop policy if exists team_read on activity_log;
create policy team_read on activity_log for select to authenticated using (is_team());

revoke all on team_members, customers, activity_log from anon, authenticated;
grant select on team_members, customers, activity_log to authenticated;
revoke execute on all functions in schema public from public, anon;
grant execute on function find_customer(text, text, text), upsert_customer(jsonb, text), undo_activity(bigint, text),
  recent_activity(integer, text, text), is_team(), crm_actor() to authenticated, service_role;


-- ===================== 0002_bookings.sql =====================
-- Triangle Resells CRM v1, phase 2: bookings (sales) and their item lines.
-- Same rules as phase 1: every write is a function, saved with its activity-log line in one transaction.
-- Stock reservation (phase 3) hooks into create / cancel / no-show; revenue and profit (phase 4) read these tables.

create table if not exists bookings (
  id uuid primary key default gen_random_uuid(),
  date date not null,
  time time,
  customer_id uuid references customers (id),
  status text not null default 'booked'
    check (status in ('booked', 'paid', 'paid_needs_check', 'done', 'no_show', 'cancelled')),
  payment_method text not null check (payment_method in ('cash', 'cash_app', 'zelle', 'stripe', 'apple_pay')),
  fulfillment text not null check (fulfillment in ('pickup', 'delivery', 'ship')),
  sale_price numeric(10, 2) not null check (sale_price >= 0),      -- item total = revenue (fees not included)
  delivery_fee numeric(10, 2) not null default 0 check (delivery_fee >= 0),  -- local delivery, NOT revenue
  shipping_fee numeric(10, 2) not null default 0 check (shipping_fee >= 0),  -- what the buyer paid for shipping
  label_cost numeric(10, 2) not null default 0 check (label_cost >= 0),      -- what we paid for the label
  location text,                       -- warehouse, meetup spot, or shipping address
  assignee text check (assignee in ('Josh', 'Chema', 'Diego')),
  source text not null default 'other' check (source in ('instagram', 'bot', 'in_person', 'text', 'referral', 'other')),
  source_account text check (source_account in ('Triangle Resells', 'Triangle Scales', 'Triangle Sales')),
  tracking_number text,
  notes text,
  status_reason text,                  -- why it was cancelled / no-show
  created_by text not null default 'System',
  is_test boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (fulfillment = 'delivery' or delivery_fee = 0),
  check (fulfillment = 'ship' or (shipping_fee = 0 and tracking_number is null)),
  check (payment_method <> 'cash' or fulfillment = 'pickup')       -- cash is pickup only (delivery cash = Josh's call)
);
create index if not exists bookings_date_idx on bookings (date);
create index if not exists bookings_customer_idx on bookings (customer_id);

create table if not exists booking_items (
  id uuid primary key default gen_random_uuid(),
  booking_id uuid not null references bookings (id) on delete cascade,
  brand text,
  item text not null check (length(trim(item)) > 0),
  color text,
  size text not null check (length(trim(size)) > 0),   -- "One Size" for bags, hats, fragrances
  qty integer not null check (qty > 0),
  unit_price numeric(10, 2) check (unit_price >= 0),
  unit_cost numeric(10, 2) check (unit_cost >= 0),     -- from the stock sheet's Cost column (phase 3)
  is_test boolean not null default false,
  created_at timestamptz not null default now()
);
create index if not exists booking_items_booking_idx on booking_items (booking_id);

drop trigger if exists bookings_log on bookings;
create trigger bookings_log after insert or update or delete on bookings for each row execute function crm_log_change();
drop trigger if exists bookings_touch on bookings;
create trigger bookings_touch before update on bookings for each row execute function crm_touch();
drop trigger if exists booking_items_log on booking_items;
create trigger booking_items_log after insert or update or delete on booking_items for each row execute function crm_log_change();

create or replace function crm_undoable() returns text[] language sql immutable as $$
  select array['customers', 'bookings', 'booking_items']
$$;

-- ---------- reading ----------
create or replace function booking_json(p_id uuid) returns jsonb
language sql stable security definer set search_path = public as $$
  select to_jsonb(b) || jsonb_build_object(
    'customer', (select to_jsonb(c) from customers c where c.id = b.customer_id),
    'items', coalesce((select jsonb_agg(to_jsonb(i) order by i.created_at, i.id) from booking_items i where i.booking_id = b.id), '[]'::jsonb)
  )
  from bookings b where b.id = p_id
$$;

create or replace function get_booking(p_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare r jsonb;
begin
  if coalesce(auth.role(), '') <> 'service_role' and not is_team() then
    raise exception 'not a team member' using errcode = '42501';
  end if;
  r := booking_json(p_id);
  if r is null then raise exception 'no booking %', p_id using errcode = 'P0002'; end if;
  return r;
end $$;

-- Calendar: every booking between two dates (inclusive), with customer and items. Test data only when asked.
create or replace function bookings_between(p_from date, p_to date, p_include_test boolean default false) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if coalesce(auth.role(), '') <> 'service_role' and not is_team() then
    raise exception 'not a team member' using errcode = '42501';
  end if;
  return coalesce((
    select jsonb_agg(booking_json(b.id) order by b.date, b.time nulls last, b.created_at)
    from bookings b where b.date between p_from and p_to and (p_include_test or not b.is_test)
  ), '[]'::jsonb);
end $$;

-- ---------- validation ----------
create or replace function crm_text(p jsonb, k text) returns text language sql immutable as $$
  select nullif(trim(p ->> k), '')
$$;

-- Checks item lines; raises a clear error (nothing gets saved) on the first problem.
create or replace function crm_check_items(p_items jsonb) returns void language plpgsql immutable as $$
declare it jsonb; n integer := 0;
begin
  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'a booking needs at least one item' using errcode = '22023';
  end if;
  for it in select * from jsonb_array_elements(p_items) loop
    n := n + 1;
    if crm_text(it, 'item') is null then raise exception 'item % has no name', n using errcode = '22023'; end if;
    if crm_text(it, 'size') is null then
      raise exception 'item % (%) has no size (use "One Size" if it has none)', n, it ->> 'item' using errcode = '22023';
    end if;
    if coalesce((it ->> 'qty')::integer, 0) < 1 then raise exception 'item % (%) needs a quantity of 1 or more', n, it ->> 'item' using errcode = '22023'; end if;
  end loop;
end $$;

create or replace function crm_insert_items(p_booking uuid, p_items jsonb, p_test boolean) returns void
language sql security definer set search_path = public as $$
  insert into booking_items (booking_id, brand, item, color, size, qty, unit_price, unit_cost, is_test)
  select p_booking, crm_text(i, 'brand'), crm_text(i, 'item'), crm_text(i, 'color'), crm_text(i, 'size'), (i ->> 'qty')::integer,
         (i ->> 'unit_price')::numeric, (i ->> 'unit_cost')::numeric, p_test
  from jsonb_array_elements(p_items) i
$$;

-- Item total from the lines' unit prices; null if any line has no price.
create or replace function crm_items_total(p_items jsonb) returns numeric language sql immutable as $$
  select case when bool_and(i ? 'unit_price' and (i ->> 'unit_price') is not null)
              then sum((i ->> 'qty')::integer * (i ->> 'unit_price')::numeric) end
  from jsonb_array_elements(p_items) i
$$;

-- Paid rule (Josh): only a Stripe payment can be marked Paid by the bot; Zelle / Cash App / cash from the bot
-- become "Paid - needs check" until a team member confirms.
create or replace function crm_paid_status(p_status text, p_payment text, p_actor text) returns text language sql immutable as $$
  select case when p_status = 'paid' and p_actor = 'Bot' and p_payment <> 'stripe' then 'paid_needs_check' else p_status end
$$;

-- ---------- writing ----------
-- p: {date, time, customer: {ig_user_id, ig_handle, name, phone}, items: [{brand, item, color, size, qty, unit_price, unit_cost}],
--     payment_method, fulfillment, sale_price?, delivery_fee?, shipping_fee?, label_cost?, location, assignee, source,
--     source_account, tracking_number, notes, status?, is_test}
create or replace function create_booking(p jsonb, p_actor text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare a text; cust jsonb; b bookings; total numeric; test boolean := coalesce((p ->> 'is_test')::boolean, false);
begin
  a := crm_begin(p_actor);
  if crm_text(p, 'date') is null then raise exception 'a booking needs a date' using errcode = '22023'; end if;
  perform crm_check_items(p -> 'items');
  total := coalesce((p ->> 'sale_price')::numeric, crm_items_total(p -> 'items'));
  if total is null then raise exception 'a booking needs a sale price (or a unit price on every item)' using errcode = '22023'; end if;
  if p ? 'customer' and jsonb_typeof(p -> 'customer') = 'object' then
    cust := upsert_customer((p -> 'customer') || jsonb_build_object('is_test', test), p_actor);
  end if;
  perform crm_begin(p_actor, a || ' booked ' || coalesce(cust ->> 'name', '@' || (cust ->> 'ig_handle'), 'a sale') || ' for ' || (p ->> 'date')
    || coalesce(' ' || crm_text(p, 'time'), ''));
  insert into bookings (date, time, customer_id, status, payment_method, fulfillment, sale_price, delivery_fee, shipping_fee,
                        label_cost, location, assignee, source, source_account, tracking_number, notes, created_by, is_test)
  values ((p ->> 'date')::date, crm_text(p, 'time')::time, (cust ->> 'id')::uuid,
          crm_paid_status(coalesce(crm_text(p, 'status'), 'booked'), p ->> 'payment_method', a),
          p ->> 'payment_method', p ->> 'fulfillment', total,
          coalesce((p ->> 'delivery_fee')::numeric, 0), coalesce((p ->> 'shipping_fee')::numeric, 0), coalesce((p ->> 'label_cost')::numeric, 0),
          crm_text(p, 'location'), crm_text(p, 'assignee'), coalesce(crm_text(p, 'source'), case when a = 'Bot' then 'bot' else 'other' end),
          crm_text(p, 'source_account'), crm_text(p, 'tracking_number'), crm_text(p, 'notes'), a, test)
  returning * into b;
  perform crm_insert_items(b.id, p -> 'items', test);
  return booking_json(b.id);
end $$;

-- Edit any fields. Items, if given, replace all lines. Date/time changes are logged as a reschedule.
create or replace function update_booking(p_id uuid, p jsonb, p_actor text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare a text; b bookings; total numeric; what text;
begin
  a := crm_begin(p_actor);
  select * into b from bookings where id = p_id for update;
  if b is null then raise exception 'no booking %', p_id using errcode = 'P0002'; end if;
  if p ? 'items' then perform crm_check_items(p -> 'items'); end if;
  what := case
    when (p ? 'date' and (p ->> 'date')::date is distinct from b.date) or (p ? 'time' and crm_text(p, 'time')::time is distinct from b.time)
      then a || ' rescheduled to ' || coalesce(p ->> 'date', b.date::text) || coalesce(' ' || coalesce(crm_text(p, 'time'), b.time::text), '')
    else a || ' edited the booking' end;
  perform crm_begin(p_actor, what);
  total := case when p ? 'sale_price' then (p ->> 'sale_price')::numeric
                when p ? 'items' then coalesce(crm_items_total(p -> 'items'), b.sale_price) else b.sale_price end;
  update bookings set
    date = coalesce((p ->> 'date')::date, date),
    time = case when p ? 'time' then crm_text(p, 'time')::time else time end,
    payment_method = coalesce(crm_text(p, 'payment_method'), payment_method),
    fulfillment = coalesce(crm_text(p, 'fulfillment'), fulfillment),
    sale_price = total,
    delivery_fee = coalesce((p ->> 'delivery_fee')::numeric, delivery_fee),
    shipping_fee = coalesce((p ->> 'shipping_fee')::numeric, shipping_fee),
    label_cost = coalesce((p ->> 'label_cost')::numeric, label_cost),
    location = case when p ? 'location' then crm_text(p, 'location') else location end,
    assignee = case when p ? 'assignee' then crm_text(p, 'assignee') else assignee end,
    source = coalesce(crm_text(p, 'source'), source),
    source_account = case when p ? 'source_account' then crm_text(p, 'source_account') else source_account end,
    tracking_number = case when p ? 'tracking_number' then crm_text(p, 'tracking_number') else tracking_number end,
    notes = case when p ? 'notes' then crm_text(p, 'notes') else notes end
  where id = p_id;
  if p ? 'items' then
    delete from booking_items where booking_id = p_id;
    perform crm_insert_items(p_id, p -> 'items', b.is_test);
  end if;
  return booking_json(p_id);
end $$;

create or replace function reschedule_booking(p_id uuid, p_date date, p_time text default null, p_actor text default null) returns jsonb
language sql security definer set search_path = public as $$
  select update_booking(p_id, jsonb_build_object('date', p_date) || case when p_time is null then '{}'::jsonb else jsonb_build_object('time', p_time) end, p_actor)
$$;

-- Booked -> Paid -> Done, plus No-show and Cancelled (with a reason). The bot's "paid" follows the Paid rule above.
create or replace function set_booking_status(p_id uuid, p_status text, p_reason text default null, p_actor text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare a text; b bookings; s text; label text;
begin
  a := crm_begin(p_actor);
  select * into b from bookings where id = p_id for update;
  if b is null then raise exception 'no booking %', p_id using errcode = 'P0002'; end if;
  s := crm_paid_status(p_status, b.payment_method, a);
  label := case s when 'booked' then 'Booked' when 'paid' then 'Paid' when 'paid_needs_check' then 'Paid - needs check'
                  when 'done' then 'Done' when 'no_show' then 'No-show' when 'cancelled' then 'Cancelled' else s end;
  perform crm_begin(p_actor, a || ' marked it ' || label || coalesce(': ' || nullif(trim(p_reason), ''), ''));
  update bookings set status = s,
    status_reason = case when s in ('cancelled', 'no_show') then nullif(trim(p_reason), '') else null end
  where id = p_id;
  return booking_json(p_id);
end $$;

create or replace function cancel_booking(p_id uuid, p_reason text default null, p_actor text default null) returns jsonb
language sql security definer set search_path = public as $$
  select set_booking_status(p_id, 'cancelled', p_reason, p_actor)
$$;

-- ---------- access ----------
alter table bookings enable row level security;
alter table booking_items enable row level security;
drop policy if exists team_read on bookings;
create policy team_read on bookings for select to authenticated using (is_team());
drop policy if exists team_read on booking_items;
create policy team_read on booking_items for select to authenticated using (is_team());
revoke all on bookings, booking_items from anon, authenticated;
grant select on bookings, booking_items to authenticated;
revoke execute on all functions in schema public from public, anon;
grant execute on function get_booking(uuid), bookings_between(date, date, boolean), create_booking(jsonb, text),
  update_booking(uuid, jsonb, text), reschedule_booking(uuid, date, text, text), set_booking_status(uuid, text, text, text),
  cancel_booking(uuid, text, text) to authenticated, service_role;

-- Live updates: the CRM screens refresh when a booking changes (Supabase realtime). Skipped where it doesn't exist.
do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    begin
      alter publication supabase_realtime add table bookings, booking_items;
    exception when duplicate_object then null;
    end;
  end if;
end $$;


-- ===================== 0003_bot_sync.sql =====================
-- Triangle Resells CRM v1: CRM -> bot. Every booking change a PERSON makes (not the bot itself) lands in an outbox the
-- bot reads every few seconds, so the bot's order, the Google Calendar event and the stock follow the CRM.
-- The bot's own changes are skipped (it already did them), so nothing loops.

create table if not exists bot_events (
  id bigserial primary key,
  at timestamptz not null default now(),
  booking_id uuid not null,
  kind text not null check (kind in ('created', 'updated', 'deleted')),
  actor text not null,
  booking jsonb not null,            -- the booking as it is now (with customer and items); for 'deleted', as it was
  previous jsonb,                    -- the booking row before the change (no items), for 'updated'
  is_test boolean not null default false
);
create index if not exists bot_events_booking_idx on bot_events (booking_id);

-- Runs at COMMIT (deferred), so the snapshot has the final items even when items were replaced in the same edit.
create or replace function crm_bot_event() returns trigger
language plpgsql security definer set search_path = public as $$
declare a text := crm_actor(); snap jsonb;
begin
  if a = 'Bot' then return null; end if;
  if tg_op = 'DELETE' then
    insert into bot_events (booking_id, kind, actor, booking, is_test) values (old.id, 'deleted', a, to_jsonb(old), old.is_test);
    return null;
  end if;
  snap := booking_json(new.id);
  if snap is null then return null; end if;      -- deleted again later in the same transaction
  insert into bot_events (booking_id, kind, actor, booking, previous, is_test)
  values (new.id, case when tg_op = 'INSERT' then 'created' else 'updated' end, a, snap,
          case when tg_op = 'UPDATE' then to_jsonb(old) end, new.is_test);
  return null;
end $$;

drop trigger if exists bookings_bot_event on bookings;
create constraint trigger bookings_bot_event after insert or update on bookings
  deferrable initially deferred for each row execute function crm_bot_event();
drop trigger if exists bookings_bot_event_delete on bookings;
create trigger bookings_bot_event_delete after delete on bookings for each row execute function crm_bot_event();

-- The bot asks: "what changed after event N?" First call with p_after = null just returns the newest id to start from.
create or replace function bot_events_after(p_after bigint, p_limit integer default 100) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if coalesce(auth.role(), '') <> 'service_role' then raise exception 'bot only' using errcode = '42501'; end if;
  if p_after is null then
    return jsonb_build_object('events', '[]'::jsonb, 'latest', coalesce((select max(id) from bot_events), 0));
  end if;
  return jsonb_build_object(
    'events', coalesce((select jsonb_agg(to_jsonb(e) order by e.id) from (
      select * from bot_events where id > p_after order by id limit least(greatest(p_limit, 1), 500)) e), '[]'::jsonb),
    'latest', coalesce((select max(id) from bot_events), 0));
end $$;

-- What the AI sees before it answers a buyer: their bookings that aren't finished (CRM is the source of truth).
create or replace function open_bookings_for(p_ig_user_id text) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if coalesce(auth.role(), '') <> 'service_role' and not is_team() then
    raise exception 'not a team member' using errcode = '42501';
  end if;
  return coalesce((
    select jsonb_agg(booking_json(b.id) order by b.date, b.time nulls last)
    from bookings b join customers c on c.id = b.customer_id
    where c.ig_user_id = p_ig_user_id and b.status in ('booked', 'paid', 'paid_needs_check')
  ), '[]'::jsonb);
end $$;

alter table bot_events enable row level security;
revoke all on bot_events from anon, authenticated;
revoke execute on all functions in schema public from public, anon;
grant execute on function bot_events_after(bigint, integer) to service_role;
grant execute on function open_bookings_for(text) to authenticated, service_role;


-- ===================== 0004_stock.sql =====================
-- Triangle Resells CRM v1, phase 3: stock.
-- The CRM keeps the live count and reserves pieces in the SAME transaction as the booking, so two buyers can never get
-- the same last piece and qty never goes below 0. BOT STOCK (the Google Sheet) stays the list people edit: the bot
-- syncs it every minute (stock_sync below): edits made on the sheet (a restock, a fix) flow in, the CRM's counts flow out.
-- TEST bookings only ever touch TEST stock (a copy of the tab), never real stock.

create table if not exists stock_items (
  id uuid primary key default gen_random_uuid(),
  key text not null,                 -- item|color|size, normalized (#2, #3 for repeated rows)
  category text,
  brand text,
  item text not null,
  color text,
  size text,
  price_list text,
  status text not null default 'for_sale' check (status in ('for_sale', 'freebie', 'not_for_sale', 'incoming', 'other')),
  notes text,
  cost numeric(10, 2),
  qty integer not null default 0 check (qty >= 0),       -- live count (what's really left)
  sheet_qty integer not null default 0,                   -- what the sheet showed / was last confirmed to show
  pending_sheet_qty integer,                              -- what the bot was asked to write, not seen on the sheet yet
  on_sheet boolean not null default true,                 -- row was removed from the sheet -> not sellable
  is_test boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (is_test, key)
);

-- Every stock change, with why: booked, cancelled, no-show, items edited, someone edited the sheet.
create table if not exists stock_moves (
  id bigserial primary key,
  at timestamptz not null default now(),
  stock_item_id uuid not null references stock_items (id),
  delta integer not null,
  qty_after integer not null,
  reason text not null,
  booking_id uuid,
  actor text not null,
  is_test boolean not null default false
);
create index if not exists stock_moves_item_idx on stock_moves (stock_item_id, id desc);

alter table booking_items add column if not exists stock_item_id uuid references stock_items (id);
alter table booking_items add column if not exists reserved boolean not null default false;

drop trigger if exists stock_items_touch on stock_items;
create trigger stock_items_touch before update on stock_items for each row execute function crm_touch();

-- Same log trigger as before, but the sync's own bookkeeping (sheet_qty, pending_sheet_qty) and the reservation flags
-- don't make log lines on their own. Real changes (qty, status, price...) still do.
create or replace function crm_log_change() returns trigger
language plpgsql security definer set search_path = public as $$
declare o jsonb; n jsonb; ch jsonb;
begin
  if tg_op = 'INSERT' then
    n := to_jsonb(new);
  elsif tg_op = 'UPDATE' then
    o := to_jsonb(old); n := to_jsonb(new);
    select jsonb_object_agg(key, jsonb_build_object('from', o -> key, 'to', value)) into ch
      from jsonb_each(n)
      where key not in ('updated_at', 'sheet_qty', 'pending_sheet_qty', 'reserved', 'stock_item_id', 'on_sheet')
        and (tg_table_name <> 'stock_items' or key <> 'qty')     -- stock counts have their own log: stock_moves
        and (o -> key) is distinct from value;
    if ch is null then return new; end if;
  else
    o := to_jsonb(old);
  end if;
  insert into activity_log (actor, action, entity, entity_id, summary, before, after, changes, undo_of, is_test)
  values (
    crm_actor(), case tg_op when 'INSERT' then 'create' when 'UPDATE' then 'update' else 'delete' end, tg_table_name,
    coalesce(n ->> 'id', o ->> 'id'), nullif(current_setting('crm.summary', true), ''), o, n, ch,
    nullif(current_setting('crm.undo_of', true), '')::bigint,
    coalesce((coalesce(n, o) ->> 'is_test')::boolean, false)
  );
  return coalesce(new, old);
end $$;

drop trigger if exists stock_items_log on stock_items;
create trigger stock_items_log after update on stock_items for each row execute function crm_log_change();

-- ---------- matching a booking line to a stock row ----------
create or replace function crm_norm(s text) returns text language sql immutable as $$
  select trim(regexp_replace(lower(coalesce(s, '')), '[^a-z0-9]+', ' ', 'g'))
$$;
create or replace function crm_size_key(s text) returns text language sql immutable as $$
  select case when crm_norm(s) in ('', 'one size', 'os') then '' else crm_norm(s) end
$$;
create or replace function crm_stock_key(p_item text, p_color text, p_size text) returns text language sql immutable as $$
  select crm_norm(p_item) || '|' || crm_norm(p_color) || '|' || crm_size_key(p_size)
$$;

-- The FOR SALE row for a line: exact item + color + size; if the line left color or size blank, the one row that fits.
create or replace function crm_find_stock(p_item text, p_color text, p_size text, p_test boolean) returns stock_items
language plpgsql stable security definer set search_path = public as $$
declare r stock_items; n integer;
begin
  select * into r from stock_items
   where is_test = p_test and on_sheet and status = 'for_sale' and split_part(key, '#', 1) = crm_stock_key(p_item, p_color, p_size)
   order by qty desc, key limit 1;
  if r.id is not null then return r; end if;
  select count(*) into n from stock_items
   where is_test = p_test and on_sheet and status = 'for_sale' and crm_norm(item) = crm_norm(p_item)
     and (crm_norm(p_color) = '' or crm_norm(color) = crm_norm(p_color))
     and (crm_size_key(p_size) = '' or crm_size_key(size) = crm_size_key(p_size));
  if n = 1 then
    select * into r from stock_items
     where is_test = p_test and on_sheet and status = 'for_sale' and crm_norm(item) = crm_norm(p_item)
       and (crm_norm(p_color) = '' or crm_norm(color) = crm_norm(p_color))
       and (crm_size_key(p_size) = '' or crm_size_key(size) = crm_size_key(p_size));
  end if;
  return r;
end $$;

create or replace function crm_line_name(i booking_items) returns text language sql immutable as $$
  select concat_ws(' ', i.item, nullif(i.color, ''), case when crm_size_key(i.size) = '' then null else i.size end)
$$;

create or replace function crm_stock_move(p_stock uuid, p_delta integer, p_reason text, p_booking uuid) returns integer
language plpgsql security definer set search_path = public as $$
declare q integer; t boolean;
begin
  update stock_items set qty = qty + p_delta where id = p_stock returning qty, is_test into q, t;
  insert into stock_moves (stock_item_id, delta, qty_after, reason, booking_id, actor, is_test)
  values (p_stock, p_delta, q, p_reason, p_booking, crm_actor(), t);
  return q;
end $$;

-- ---------- reserving: lines take stock when they're on an open booking, give it back when they're not ----------
create or replace function crm_booking_open(p_status text) returns boolean language sql immutable as $$
  select p_status not in ('cancelled', 'no_show')
$$;

-- A new line on an open booking takes its pieces. Not enough -> the whole booking (or edit) is refused.
create or replace function crm_reserve_line() returns trigger
language plpgsql security definer set search_path = public as $$
declare s stock_items; st text;
begin
  select status into st from bookings where id = new.booking_id;
  if st is null or not crm_booking_open(st) then return new; end if;
  s := crm_find_stock(new.item, new.color, new.size, new.is_test);
  if s.id is null then
    raise exception '% isn''t a FOR SALE item on BOT STOCK%', crm_line_name(new),
      case when new.is_test then ' (TEST stock)' else '' end using errcode = '22023';
  end if;
  if s.qty < new.qty then
    raise exception 'only % left of % (asked for %)', s.qty, crm_line_name(new), new.qty using errcode = 'TR409';
  end if;
  perform crm_stock_move(s.id, -new.qty, 'booked', new.booking_id);
  new.stock_item_id := s.id;
  new.reserved := true;
  if new.unit_cost is null then new.unit_cost := s.cost; end if;   -- cost from the sheet, for profit
  return new;
end $$;
drop trigger if exists booking_items_reserve on booking_items;
create trigger booking_items_reserve before insert on booking_items for each row execute function crm_reserve_line();

-- A removed line (items edited, booking deleted / undone) gives its pieces back.
create or replace function crm_release_line() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if old.reserved and old.stock_item_id is not null then
    perform crm_stock_move(old.stock_item_id, old.qty, 'items edited or booking removed', old.booking_id);
  end if;
  return old;
end $$;
drop trigger if exists booking_items_release on booking_items;
create trigger booking_items_release before delete on booking_items for each row execute function crm_release_line();

-- Cancelled / No-show gives the pieces back; reopening takes them again (refused if they're gone meanwhile).
create or replace function crm_status_stock() returns trigger
language plpgsql security definer set search_path = public as $$
declare i booking_items; s stock_items;
begin
  if crm_booking_open(old.status) = crm_booking_open(new.status) then return new; end if;
  for i in select * from booking_items where booking_id = new.id order by created_at, id loop
    if not crm_booking_open(new.status) then
      if i.reserved then
        perform crm_stock_move(i.stock_item_id, i.qty, case new.status when 'no_show' then 'no-show' else 'cancelled' end, new.id);
        update booking_items set reserved = false where id = i.id;
      end if;
    else
      s := crm_find_stock(i.item, i.color, i.size, i.is_test);
      if s.id is null then raise exception '% isn''t a FOR SALE item on BOT STOCK', crm_line_name(i) using errcode = '22023'; end if;
      if s.qty < i.qty then raise exception 'only % left of % (asked for %)', s.qty, crm_line_name(i), i.qty using errcode = 'TR409'; end if;
      perform crm_stock_move(s.id, -i.qty, 'reopened', new.id);
      update booking_items set reserved = true, stock_item_id = s.id where id = i.id;
    end if;
  end loop;
  return new;
end $$;
drop trigger if exists bookings_status_stock on bookings;
create trigger bookings_status_stock after update of status on bookings for each row execute function crm_status_stock();

-- ---------- sheet <-> CRM sync (the bot runs this every minute) ----------
-- p_rows: the BOT STOCK rows as read [{category, brand, item, color, size, qty, price_list, status, notes, cost}].
-- Returns the counts the bot must write back to the sheet: [{item, color, size, occurrence, qty}].
create or replace function stock_sync(p_rows jsonb, p_is_test boolean default false, p_actor text default 'Bot') returns jsonb
language plpgsql security definer set search_path = public as $$
declare r jsonb; k text; base text; seen text[] := '{}'; occ integer; e stock_items; s integer; d integer; changed integer := 0;
begin
  perform crm_begin(p_actor, 'Stock sync with BOT STOCK');
  if coalesce(auth.role(), '') <> 'service_role' then raise exception 'bot only' using errcode = '42501'; end if;
  if jsonb_typeof(p_rows) <> 'array' then raise exception 'rows must be a list' using errcode = '22023'; end if;
  for r in select * from jsonb_array_elements(p_rows) loop
    continue when nullif(trim(r ->> 'item'), '') is null;
    base := crm_stock_key(r ->> 'item', r ->> 'color', r ->> 'size');
    occ := (select count(*) from unnest(seen) x where x = base) + 1;
    seen := seen || base;
    k := base || case when occ > 1 then '#' || occ else '' end;
    s := greatest(coalesce((regexp_match(coalesce(r ->> 'qty', ''), '\d+'))[1]::integer, 0), 0);
    select * into e from stock_items where is_test = p_is_test and key = k for update;
    if e.id is null then
      insert into stock_items (key, category, brand, item, color, size, price_list, status, notes, cost, qty, sheet_qty, is_test)
      values (k, nullif(r ->> 'category', ''), nullif(r ->> 'brand', ''), r ->> 'item', nullif(r ->> 'color', ''), nullif(r ->> 'size', ''),
              nullif(r ->> 'price_list', ''), coalesce(nullif(r ->> 'status', ''), 'other'), nullif(r ->> 'notes', ''),
              nullif(r ->> 'cost', '')::numeric, s, s, p_is_test);
      continue;
    end if;
    if e.pending_sheet_qty is not null and s = e.pending_sheet_qty then
      update stock_items set sheet_qty = s, pending_sheet_qty = null where id = e.id;      -- our write landed
    elsif s <> coalesce(e.pending_sheet_qty, e.sheet_qty) and not (e.pending_sheet_qty is not null and s = e.sheet_qty) then
      -- Someone changed the number on the sheet (restock, count fix): apply the same change to the live count.
      d := s - coalesce(e.pending_sheet_qty, e.sheet_qty);
      d := greatest(d, -e.qty);
      if d <> 0 then perform crm_stock_move(e.id, d, 'BOT STOCK edited on the sheet', null); changed := changed + 1; end if;
      update stock_items set sheet_qty = s, pending_sheet_qty = null where id = e.id;
    end if;
    update stock_items set
      category = nullif(r ->> 'category', ''), brand = nullif(r ->> 'brand', ''), item = r ->> 'item',
      color = nullif(r ->> 'color', ''), size = nullif(r ->> 'size', ''), price_list = nullif(r ->> 'price_list', ''),
      status = coalesce(nullif(r ->> 'status', ''), 'other'), notes = nullif(r ->> 'notes', ''),
      cost = nullif(r ->> 'cost', '')::numeric, on_sheet = true
    where id = e.id;
  end loop;
  -- Rows taken off the sheet can't be sold anymore.
  update stock_items si set on_sheet = false where si.is_test = p_is_test and si.on_sheet and si.key <> all (
    select b || case when n > 1 then '#' || n else '' end from (
      select b, row_number() over (partition by b) n from unnest(seen) b) x);
  -- What the sheet should show now.
  update stock_items set pending_sheet_qty = qty
   where is_test = p_is_test and on_sheet and qty <> coalesce(pending_sheet_qty, sheet_qty);
  return jsonb_build_object(
    'sheet_edits_applied', changed,
    'writes', coalesce((select jsonb_agg(jsonb_build_object('item', item, 'color', color, 'size', size,
        'occurrence', coalesce(nullif(split_part(key, '#', 2), '')::integer, 1), 'qty', pending_sheet_qty) order by key)
      from stock_items where is_test = p_is_test and on_sheet and pending_sheet_qty is not null), '[]'::jsonb));
end $$;

-- ---------- reading ----------
create or replace function stock_list(p_is_test boolean default false) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if coalesce(auth.role(), '') <> 'service_role' and not is_team() then raise exception 'not a team member' using errcode = '42501'; end if;
  return coalesce((select jsonb_agg(to_jsonb(s) order by s.qty = 0 desc, s.brand, s.item, s.color, s.size)
    from stock_items s where s.is_test = p_is_test and s.on_sheet), '[]'::jsonb);
end $$;

create or replace function stock_history(p_stock uuid, p_limit integer default 50) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if coalesce(auth.role(), '') <> 'service_role' and not is_team() then raise exception 'not a team member' using errcode = '42501'; end if;
  return coalesce((select jsonb_agg(to_jsonb(m) order by m.id desc) from (
    select * from stock_moves where stock_item_id = p_stock order by id desc limit least(greatest(p_limit, 1), 500)) m), '[]'::jsonb);
end $$;

alter table stock_items enable row level security;
alter table stock_moves enable row level security;
drop policy if exists team_read on stock_items;
create policy team_read on stock_items for select to authenticated using (is_team());
drop policy if exists team_read on stock_moves;
create policy team_read on stock_moves for select to authenticated using (is_team());
revoke all on stock_items, stock_moves from anon, authenticated;
grant select on stock_items, stock_moves to authenticated;
revoke execute on all functions in schema public from public, anon;
grant execute on function stock_sync(jsonb, boolean, text) to service_role;
grant execute on function stock_list(boolean), stock_history(uuid, integer) to authenticated, service_role;

do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    begin
      alter publication supabase_realtime add table stock_items;
    exception when duplicate_object then null;
    end;
  end if;
end $$;


-- ===================== 0005_reports.sql =====================
-- Triangle Resells CRM v1, phase 4: revenue, profit, drill-down, customers, cash per person, DM counts.
-- Revenue = sale_price of DONE bookings, in the month of the booking date. Delivery fees and shipping charged are NOT
-- revenue. Profit = revenue - item cost - label cost. A sale with an item that has no cost is flagged, never guessed.

-- ---------- cash accountability ----------
alter table bookings add column if not exists cash_collected_by text check (cash_collected_by in ('Josh', 'Chema', 'Diego'));
alter table bookings add column if not exists cash_collected_at timestamptz;

-- Cash marked Paid or Done: who collected it (the person who tapped it, or who was fulfilling if the bot did) and when.
create or replace function crm_cash_collect() returns trigger
language plpgsql security definer set search_path = public as $$
declare a text := crm_actor();
begin
  if tg_op = 'INSERT' then
    if new.payment_method = 'cash' and new.status in ('paid', 'done') then
      new.cash_collected_at := now();
      new.cash_collected_by := coalesce(new.cash_collected_by, case when a in ('Josh', 'Chema', 'Diego') then a end, new.assignee);
    end if;
    return new;
  end if;
  if new.payment_method = 'cash' and new.status in ('paid', 'done') and new.cash_collected_at is null then
    new.cash_collected_at := now();
    new.cash_collected_by := coalesce(new.cash_collected_by, case when a in ('Josh', 'Chema', 'Diego') then a end, new.assignee);
  elsif new.status not in ('paid', 'done') and old.status in ('paid', 'done') and new.payment_method = 'cash' then
    new.cash_collected_at := null;   -- un-marked (or cancelled after all): not collected
    new.cash_collected_by := null;
  end if;
  return new;
end $$;
drop trigger if exists bookings_cash on bookings;
create trigger bookings_cash before insert or update of status on bookings for each row execute function crm_cash_collect();

-- ---------- one row per sale, with its cost and profit ----------
create or replace function crm_sale_row(b bookings) returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'id', b.id, 'date', b.date, 'time', b.time, 'status', b.status,
    'customer', (select jsonb_build_object('id', c.id, 'ig_handle', c.ig_handle, 'name', c.name, 'phone', c.phone) from customers c where c.id = b.customer_id),
    'items', coalesce((select jsonb_agg(jsonb_build_object('brand', i.brand, 'item', i.item, 'color', i.color, 'size', i.size, 'qty', i.qty,
        'unit_price', i.unit_price, 'unit_cost', i.unit_cost) order by i.created_at, i.id) from booking_items i where i.booking_id = b.id), '[]'::jsonb),
    'revenue', b.sale_price,
    'item_cost', coalesce((select sum(i.qty * i.unit_cost) from booking_items i where i.booking_id = b.id), 0),
    'label_cost', b.label_cost,
    'cost_missing', exists (select 1 from booking_items i where i.booking_id = b.id and i.unit_cost is null),
    'profit', b.sale_price - coalesce((select sum(i.qty * i.unit_cost) from booking_items i where i.booking_id = b.id), 0) - b.label_cost,
    'delivery_fee', b.delivery_fee, 'shipping_fee', b.shipping_fee,
    'payment_method', b.payment_method, 'fulfillment', b.fulfillment, 'location', b.location,
    'assignee', b.assignee, 'source', b.source, 'source_account', b.source_account, 'tracking_number', b.tracking_number,
    'cash_collected_by', b.cash_collected_by, 'is_test', b.is_test)
$$;

-- Filters: {assignee, payment_method, fulfillment, source, source_account}. Blank = all.
create or replace function crm_sale_matches(b bookings, f jsonb) returns boolean language sql immutable as $$
  select (nullif(f ->> 'assignee', '') is null or b.assignee = f ->> 'assignee')
     and (nullif(f ->> 'payment_method', '') is null or b.payment_method = f ->> 'payment_method')
     and (nullif(f ->> 'fulfillment', '') is null or b.fulfillment = f ->> 'fulfillment')
     and (nullif(f ->> 'source', '') is null or b.source = f ->> 'source')
     and (nullif(f ->> 'source_account', '') is null or coalesce(b.source_account, 'none') = f ->> 'source_account')
$$;

create or replace function crm_team_or_service() returns void language plpgsql stable security definer set search_path = public as $$
begin
  if coalesce(auth.role(), '') <> 'service_role' and not is_team() then raise exception 'not a team member' using errcode = '42501'; end if;
end $$;

-- The drill-down: every Done sale in [p_from, p_to] with totals computed from those same rows, so they always add up.
create or replace function sales_report(p_from date, p_to date, p_filters jsonb default '{}', p_include_test boolean default false) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare rows jsonb;
begin
  perform crm_team_or_service();
  select coalesce(jsonb_agg(crm_sale_row(b) order by b.date, b.time nulls last, b.created_at), '[]'::jsonb) into rows
    from bookings b
   where b.status = 'done' and b.date between p_from and p_to and (p_include_test or not b.is_test)
     and crm_sale_matches(b, coalesce(p_filters, '{}'));
  return jsonb_build_object(
    'from', p_from, 'to', p_to,
    'totals', (select jsonb_build_object(
        'sales', count(*),
        'revenue', coalesce(sum((r ->> 'revenue')::numeric), 0),
        'item_cost', coalesce(sum((r ->> 'item_cost')::numeric), 0),
        'label_cost', coalesce(sum((r ->> 'label_cost')::numeric), 0),
        'profit', coalesce(sum((r ->> 'profit')::numeric), 0),
        'delivery_fees', coalesce(sum((r ->> 'delivery_fee')::numeric), 0),
        'sales_missing_cost', count(*) filter (where (r ->> 'cost_missing')::boolean))
      from jsonb_array_elements(rows) r),
    'by_account', coalesce((select jsonb_agg(jsonb_build_object('account', acct, 'revenue', rev, 'profit', prof, 'sales', n) order by rev desc) from (
        select coalesce(r ->> 'source_account', 'In person / other') acct, sum((r ->> 'revenue')::numeric) rev, sum((r ->> 'profit')::numeric) prof, count(*) n
          from jsonb_array_elements(rows) r group by 1) x), '[]'::jsonb),
    'sales', rows);
end $$;

-- The chart: Done revenue and profit for each of the last p_months months (oldest first), plus what's still open.
create or replace function monthly_report(p_months integer default 12, p_filters jsonb default '{}', p_include_test boolean default false,
                                          p_today date default (now() at time zone 'America/New_York')::date) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  perform crm_team_or_service();
  return (select jsonb_agg(jsonb_build_object('month', to_char(m, 'YYYY-MM'),
      'revenue', coalesce(x.rev, 0), 'profit', coalesce(x.prof, 0), 'sales', coalesce(x.n, 0), 'open', coalesce(o.open, 0)) order by m)
    from generate_series(date_trunc('month', p_today) - make_interval(months => least(greatest(p_months, 1), 60) - 1), date_trunc('month', p_today), interval '1 month') m
    left join (
      select date_trunc('month', b.date) mon, sum(b.sale_price) rev,
             sum(b.sale_price - coalesce((select sum(i.qty * i.unit_cost) from booking_items i where i.booking_id = b.id), 0) - b.label_cost) prof, count(*) n
        from bookings b where b.status = 'done' and (p_include_test or not b.is_test) and crm_sale_matches(b, coalesce(p_filters, '{}'))
       group by 1) x on x.mon = m
    left join (
      select date_trunc('month', b.date) mon, sum(b.sale_price) open
        from bookings b where b.status in ('booked', 'paid', 'paid_needs_check') and (p_include_test or not b.is_test) and crm_sale_matches(b, coalesce(p_filters, '{}'))
       group by 1) o on o.mon = m);
end $$;

-- ---------- customers ----------
create or replace function crm_customer_row(c customers) returns jsonb
language sql stable security definer set search_path = public as $$
  select to_jsonb(c) || jsonb_build_object(
    'orders', (select count(*) from bookings b where b.customer_id = c.id and b.status = 'done'),
    'open_orders', (select count(*) from bookings b where b.customer_id = c.id and b.status in ('booked', 'paid', 'paid_needs_check')),
    'total_spent', coalesce((select sum(b.sale_price) from bookings b where b.customer_id = c.id and b.status = 'done'), 0),
    'last_order', (select max(b.date) from bookings b where b.customer_id = c.id and b.status not in ('cancelled', 'no_show')),
    'no_shows', (select count(*) from bookings b where b.customer_id = c.id and b.status = 'no_show'))
$$;

-- p_sort: top_spenders | lowest_spenders | most_dms | repeat_buyers | recent
create or replace function customers_report(p_sort text default 'top_spenders', p_limit integer default 100, p_include_test boolean default false, p_search text default null) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  perform crm_team_or_service();
  return coalesce((select jsonb_agg(r order by n) from (
    select r, row_number() over (order by
        case when p_sort = 'top_spenders' then -(r ->> 'total_spent')::numeric when p_sort = 'lowest_spenders' then (r ->> 'total_spent')::numeric end nulls last,
        case when p_sort = 'most_dms' then -(r ->> 'dm_conversations')::integer when p_sort = 'repeat_buyers' then -(r ->> 'orders')::integer end nulls last,
        r ->> 'last_order' desc nulls last, r ->> 'created_at' desc) n
      from (
        select crm_customer_row(c) r from customers c
         where (p_include_test or not c.is_test)
           and (nullif(trim(p_search), '') is null or c.ig_handle ilike '%' || trim(p_search) || '%'
                or c.name ilike '%' || trim(p_search) || '%' or c.phone ilike '%' || trim(p_search) || '%')
      ) x
     where p_sort <> 'repeat_buyers' or (r ->> 'orders')::integer >= 2
     order by n
     limit least(greatest(p_limit, 1), 1000)) y), '[]'::jsonb);
end $$;

-- Every order a customer has, newest first.
create or replace function customer_orders(p_customer uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  perform crm_team_or_service();
  return jsonb_build_object(
    'customer', (select crm_customer_row(c) from customers c where c.id = p_customer),
    'orders', coalesce((select jsonb_agg(crm_sale_row(b) order by b.date desc, b.time desc nulls last) from bookings b where b.customer_id = p_customer), '[]'::jsonb));
end $$;

-- A new DM conversation started (the bot calls this): counts toward "most active in DMs".
create or replace function record_dm(p_ig_user_id text, p_ig_handle text default null, p_actor text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare c jsonb;
begin
  c := upsert_customer(jsonb_build_object('ig_user_id', p_ig_user_id, 'ig_handle', p_ig_handle), p_actor);
  perform crm_begin(p_actor, 'New DM conversation');
  update customers set dm_conversations = dm_conversations + 1 where id = (c ->> 'id')::uuid;
  return (select crm_customer_row(x) from customers x where x.id = (c ->> 'id')::uuid);
end $$;

-- What the bot reads before it answers: the buyer's history and their open bookings.
create or replace function buyer_context(p_ig_user_id text) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  perform crm_team_or_service();
  return jsonb_build_object(
    'customer', (select crm_customer_row(c) from customers c where c.ig_user_id = p_ig_user_id),
    'bookings', open_bookings_for(p_ig_user_id));
end $$;

-- ---------- cash per person per day ----------
create or replace function cash_report(p_day date default (now() at time zone 'America/New_York')::date, p_include_test boolean default false) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  perform crm_team_or_service();
  return jsonb_build_object('day', p_day, 'people', (
    select jsonb_agg(jsonb_build_object('name', t.name,
        'total', coalesce((select sum(b.sale_price) from bookings b where b.cash_collected_by = t.name
                            and (b.cash_collected_at at time zone 'America/New_York')::date = p_day and (p_include_test or not b.is_test)), 0),
        'bookings', coalesce((select jsonb_agg(crm_sale_row(b) || jsonb_build_object('cash_collected_at', b.cash_collected_at) order by b.cash_collected_at)
                                from bookings b where b.cash_collected_by = t.name
                                 and (b.cash_collected_at at time zone 'America/New_York')::date = p_day and (p_include_test or not b.is_test)), '[]'::jsonb))
      order by t.name)
    from team_members t));
end $$;

revoke execute on all functions in schema public from public, anon;
grant execute on function sales_report(date, date, jsonb, boolean), monthly_report(integer, jsonb, boolean, date),
  customers_report(text, integer, boolean, text), customer_orders(uuid), cash_report(date, boolean), buyer_context(text)
  to authenticated, service_role;
grant execute on function record_dm(text, text, text) to service_role;


-- ===================== 0006_restocks.sql =====================
-- Triangle Resells CRM v1: restocks and the team's stock view.
-- A restock is logged while it's coming (from a screenshot or by hand), then marked received: the pieces are added to
-- the live count, INCOMING rows become FOR SALE, and items that aren't on BOT STOCK yet get a row added by the bot.
-- "Sold this restock" = Done sales of the item dated on or after the day the restock landed.

create table if not exists restocks (
  id uuid primary key default gen_random_uuid(),
  name text not null check (length(trim(name)) > 0),        -- e.g. "Nov 16-17 restock"
  status text not null default 'incoming' check (status in ('incoming', 'received')),
  expected_date date,
  received_at timestamptz,
  notes text,
  created_by text not null default 'System',
  is_test boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists restock_items (
  id uuid primary key default gen_random_uuid(),
  restock_id uuid not null references restocks (id) on delete cascade,
  category text,
  brand text,
  item text not null check (length(trim(item)) > 0),
  color text,
  size text,
  qty_expected integer not null check (qty_expected >= 0),
  qty_received integer check (qty_received >= 0),
  price_list text,
  unit_cost numeric(10, 2) check (unit_cost >= 0),
  stock_item_id uuid references stock_items (id),
  is_test boolean not null default false,
  created_at timestamptz not null default now()
);
create index if not exists restock_items_restock_idx on restock_items (restock_id);

-- Stock rows the CRM made (a new item in a restock) wait for the bot to add them to BOT STOCK;
-- a status the CRM changed (INCOMING -> FOR SALE) waits for the bot to write it, and the sync keeps the CRM's value meanwhile.
alter table stock_items add column if not exists needs_sheet_row boolean not null default false;
alter table stock_items add column if not exists pending_sheet_status text;

drop trigger if exists restocks_touch on restocks;
create trigger restocks_touch before update on restocks for each row execute function crm_touch();
drop trigger if exists restocks_log on restocks;
create trigger restocks_log after insert or update or delete on restocks for each row execute function crm_log_change();
drop trigger if exists restock_items_log on restock_items;
create trigger restock_items_log after insert or update or delete on restock_items for each row execute function crm_log_change();

create or replace function crm_undoable() returns text[] language sql immutable as $$
  select array['customers', 'bookings', 'booking_items', 'restocks', 'restock_items']
$$;

create or replace function restock_json(p_id uuid) returns jsonb
language sql stable security definer set search_path = public as $$
  select to_jsonb(r) || jsonb_build_object('items', coalesce((
    select jsonb_agg(to_jsonb(i) order by i.brand nulls last, i.item, i.color, i.size, i.created_at) from restock_items i where i.restock_id = r.id), '[]'::jsonb))
  from restocks r where r.id = p_id
$$;

create or replace function crm_check_restock_items(p_items jsonb) returns void language plpgsql immutable as $$
declare it jsonb; n integer := 0;
begin
  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'a restock needs at least one item' using errcode = '22023';
  end if;
  for it in select * from jsonb_array_elements(p_items) loop
    n := n + 1;
    if nullif(trim(it ->> 'item'), '') is null then raise exception 'restock item % has no name', n using errcode = '22023'; end if;
    if coalesce((it ->> 'qty_expected')::integer, -1) < 0 then raise exception 'restock item % (%) needs a quantity', n, it ->> 'item' using errcode = '22023'; end if;
  end loop;
end $$;

create or replace function crm_insert_restock_items(p_restock uuid, p_items jsonb, p_test boolean) returns void
language sql security definer set search_path = public as $$
  insert into restock_items (restock_id, category, brand, item, color, size, qty_expected, price_list, unit_cost, is_test)
  select p_restock, crm_text(i, 'category'), crm_text(i, 'brand'), crm_text(i, 'item'), crm_text(i, 'color'), crm_text(i, 'size'),
         (i ->> 'qty_expected')::integer, crm_text(i, 'price_list'), (i ->> 'unit_cost')::numeric, p_test
  from jsonb_array_elements(p_items) i
$$;

-- p: {name, expected_date, notes, is_test, items: [{category, brand, item, color, size, qty_expected, price_list, unit_cost}]}
create or replace function create_restock(p jsonb, p_actor text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare a text; r restocks; test boolean := coalesce((p ->> 'is_test')::boolean, false);
begin
  a := crm_begin(p_actor);
  perform crm_check_restock_items(p -> 'items');
  perform crm_begin(p_actor, a || ' logged an incoming restock: ' || coalesce(crm_text(p, 'name'), '?'));
  insert into restocks (name, expected_date, notes, created_by, is_test)
  values (coalesce(crm_text(p, 'name'), 'Restock'), (p ->> 'expected_date')::date, crm_text(p, 'notes'), a, test)
  returning * into r;
  perform crm_insert_restock_items(r.id, p -> 'items', test);
  return restock_json(r.id);
end $$;

-- Edit while it's still coming (name, date, notes; items replace all lines).
create or replace function update_restock(p_id uuid, p jsonb, p_actor text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare a text; r restocks;
begin
  a := crm_begin(p_actor);
  select * into r from restocks where id = p_id for update;
  if r is null then raise exception 'no restock %', p_id using errcode = 'P0002'; end if;
  if r.status = 'received' then raise exception 'this restock was already received' using errcode = '22023'; end if;
  if p ? 'items' then perform crm_check_restock_items(p -> 'items'); end if;
  perform crm_begin(p_actor, a || ' edited the incoming restock ' || r.name);
  update restocks set name = coalesce(crm_text(p, 'name'), name),
    expected_date = case when p ? 'expected_date' then (p ->> 'expected_date')::date else expected_date end,
    notes = case when p ? 'notes' then crm_text(p, 'notes') else notes end
  where id = p_id;
  if p ? 'items' then
    delete from restock_items where restock_id = p_id;
    perform crm_insert_restock_items(p_id, p -> 'items', r.is_test);
  end if;
  return restock_json(p_id);
end $$;

-- It landed. p_received: optional [{id, qty_received}] when the count differs from what was expected.
create or replace function receive_restock(p_id uuid, p_received jsonb default '[]', p_actor text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare a text; r restocks; i restock_items; got integer; s stock_items; k text;
begin
  a := crm_begin(p_actor);
  select * into r from restocks where id = p_id for update;
  if r is null then raise exception 'no restock %', p_id using errcode = 'P0002'; end if;
  if r.status = 'received' then raise exception 'this restock was already received' using errcode = '22023'; end if;
  perform crm_begin(p_actor, a || ' received the restock ' || r.name);
  for i in select * from restock_items where restock_id = p_id order by created_at, id loop
    got := coalesce((select (x ->> 'qty_received')::integer from jsonb_array_elements(coalesce(p_received, '[]')) x where x ->> 'id' = i.id::text), i.qty_expected);
    if got < 0 then raise exception 'received count for % can''t be negative', i.item using errcode = '22023'; end if;
    k := crm_stock_key(i.item, i.color, i.size);
    select * into s from stock_items where is_test = i.is_test and split_part(key, '#', 1) = k order by key limit 1 for update;
    if s.id is null then
      -- A new item: the CRM makes the stock row now; the bot adds it to BOT STOCK on its next sync.
      insert into stock_items (key, category, brand, item, color, size, price_list, status, cost, qty, sheet_qty, needs_sheet_row, is_test)
      values (k, i.category, i.brand, i.item, i.color, i.size, i.price_list, 'for_sale', i.unit_cost, 0, 0, true, i.is_test)
      returning * into s;
    elsif s.status <> 'for_sale' or not s.on_sheet then
      update stock_items set status = 'for_sale', pending_sheet_status = 'for_sale', on_sheet = true,
        cost = coalesce(i.unit_cost, cost), price_list = coalesce(i.price_list, price_list)
      where id = s.id;
    elsif i.unit_cost is not null and s.cost is distinct from i.unit_cost then
      update stock_items set cost = i.unit_cost where id = s.id;
    end if;
    if got > 0 then perform crm_stock_move(s.id, got, 'restock: ' || r.name, null); end if;
    update restock_items set qty_received = got, stock_item_id = s.id where id = i.id;
  end loop;
  update restocks set status = 'received', received_at = now() where id = p_id;
  return restock_json(p_id);
end $$;

create or replace function restocks_list(p_include_test boolean default false) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  perform crm_team_or_service();
  return coalesce((select jsonb_agg(restock_json(r.id) order by r.status = 'received', coalesce(r.received_at, r.created_at) desc)
    from restocks r where p_include_test or not r.is_test), '[]'::jsonb);
end $$;

-- ---------- the team's stock view ----------
-- Per item: free to sell, reserved (booked, not done yet), sold (Done) since the latest restock of it landed,
-- what that restock brought in, and all-time sold.
create or replace function stock_overview(p_is_test boolean default false) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  perform crm_team_or_service();
  return coalesce((select jsonb_agg(x order by (x ->> 'free')::integer = 0 and x ->> 'status' = 'for_sale' desc, x ->> 'brand', x ->> 'item', x ->> 'color', x ->> 'size') from (
    select jsonb_build_object(
      'id', s.id, 'brand', s.brand, 'item', s.item, 'color', s.color, 'size', s.size, 'status', s.status, 'price_list', s.price_list, 'cost', s.cost,
      'free', s.qty,
      'reserved', coalesce((select sum(bi.qty) from booking_items bi join bookings b on b.id = bi.booking_id
                             where bi.stock_item_id = s.id and bi.reserved and b.status in ('booked', 'paid', 'paid_needs_check')), 0),
      'restock', lr.name, 'restock_received', lr.received_at, 'came_in', coalesce(lr.qty_received, 0),
      'sold_since_restock', coalesce((select sum(bi.qty) from booking_items bi join bookings b on b.id = bi.booking_id
                             where bi.stock_item_id = s.id and b.status = 'done'
                               and (lr.received_at is null or b.date >= (lr.received_at at time zone 'America/New_York')::date)), 0),
      'sold_all_time', coalesce((select sum(bi.qty) from booking_items bi join bookings b on b.id = bi.booking_id
                             where bi.stock_item_id = s.id and b.status = 'done'), 0),
      'needs_sheet_row', s.needs_sheet_row) x
    from stock_items s
    left join lateral (
      select r.name, r.received_at, ri.qty_received from restock_items ri join restocks r on r.id = ri.restock_id
       where ri.stock_item_id = s.id and r.status = 'received' order by r.received_at desc limit 1) lr on true
    where s.is_test = p_is_test and (s.on_sheet or s.needs_sheet_row)) y), '[]'::jsonb);
end $$;

-- ---------- sheet sync, now with added rows and status changes ----------
create or replace function stock_sync(p_rows jsonb, p_is_test boolean default false, p_actor text default 'Bot') returns jsonb
language plpgsql security definer set search_path = public as $$
declare r jsonb; k text; base text; seen text[] := '{}'; occ integer; e stock_items; s integer; d integer; changed integer := 0; st text;
begin
  perform crm_begin(p_actor, 'Stock sync with BOT STOCK');
  if coalesce(auth.role(), '') <> 'service_role' then raise exception 'bot only' using errcode = '42501'; end if;
  if jsonb_typeof(p_rows) <> 'array' then raise exception 'rows must be a list' using errcode = '22023'; end if;
  for r in select * from jsonb_array_elements(p_rows) loop
    continue when nullif(trim(r ->> 'item'), '') is null;
    base := crm_stock_key(r ->> 'item', r ->> 'color', r ->> 'size');
    occ := (select count(*) from unnest(seen) x where x = base) + 1;
    seen := seen || base;
    k := base || case when occ > 1 then '#' || occ else '' end;
    s := greatest(coalesce((regexp_match(coalesce(r ->> 'qty', ''), '\d+'))[1]::integer, 0), 0);
    st := coalesce(nullif(r ->> 'status', ''), 'other');
    select * into e from stock_items where is_test = p_is_test and key = k for update;
    if e.id is null then
      insert into stock_items (key, category, brand, item, color, size, price_list, status, notes, cost, qty, sheet_qty, is_test)
      values (k, nullif(r ->> 'category', ''), nullif(r ->> 'brand', ''), r ->> 'item', nullif(r ->> 'color', ''), nullif(r ->> 'size', ''),
              nullif(r ->> 'price_list', ''), st, nullif(r ->> 'notes', ''), nullif(r ->> 'cost', '')::numeric, s, s, p_is_test);
      continue;
    end if;
    if e.needs_sheet_row then
      -- The row the bot added for a restock is on the sheet now: from here it syncs like any other row.
      update stock_items set needs_sheet_row = false, sheet_qty = s, pending_sheet_qty = case when s = qty then null else qty end where id = e.id;
    elsif e.pending_sheet_qty is not null and s = e.pending_sheet_qty then
      update stock_items set sheet_qty = s, pending_sheet_qty = null where id = e.id;
    elsif s <> coalesce(e.pending_sheet_qty, e.sheet_qty) and not (e.pending_sheet_qty is not null and s = e.sheet_qty) then
      d := s - coalesce(e.pending_sheet_qty, e.sheet_qty);
      d := greatest(d, -e.qty);
      if d <> 0 then perform crm_stock_move(e.id, d, 'BOT STOCK edited on the sheet', null); changed := changed + 1; end if;
      update stock_items set sheet_qty = s, pending_sheet_qty = null where id = e.id;
    end if;
    update stock_items set
      category = nullif(r ->> 'category', ''), brand = nullif(r ->> 'brand', ''), item = r ->> 'item',
      color = nullif(r ->> 'color', ''), size = nullif(r ->> 'size', ''), price_list = coalesce(nullif(r ->> 'price_list', ''), price_list),
      -- A status the CRM changed (restock received) wins until the sheet shows it.
      status = case when pending_sheet_status is null or pending_sheet_status = st then st else pending_sheet_status end,
      pending_sheet_status = case when pending_sheet_status = st then null else pending_sheet_status end,
      notes = nullif(r ->> 'notes', ''), cost = coalesce(nullif(r ->> 'cost', '')::numeric, cost), on_sheet = true
    where id = e.id;
  end loop;
  -- Rows taken off the sheet can't be sold anymore (rows still waiting to be added are kept).
  update stock_items si set on_sheet = false where si.is_test = p_is_test and si.on_sheet and not si.needs_sheet_row and si.key <> all (
    select b || case when n > 1 then '#' || n else '' end from (
      select b, row_number() over (partition by b) n from unnest(seen) b) x);
  update stock_items set pending_sheet_qty = qty
   where is_test = p_is_test and on_sheet and not needs_sheet_row and qty <> coalesce(pending_sheet_qty, sheet_qty);
  return jsonb_build_object(
    'sheet_edits_applied', changed,
    'writes', coalesce((select jsonb_agg(jsonb_build_object('item', item, 'color', color, 'size', size,
        'occurrence', coalesce(nullif(split_part(key, '#', 2), '')::integer, 1), 'qty', coalesce(pending_sheet_qty, qty),
        'status', pending_sheet_status) order by key)
      from stock_items where is_test = p_is_test and on_sheet and not needs_sheet_row
        and (pending_sheet_qty is not null or pending_sheet_status is not null)), '[]'::jsonb),
    'add_rows', coalesce((select jsonb_agg(jsonb_build_object('category', category, 'brand', brand, 'item', item, 'color', color, 'size', size,
        'qty', qty, 'price_list', price_list, 'status', status, 'cost', cost) order by created_at)
      from stock_items where is_test = p_is_test and needs_sheet_row), '[]'::jsonb));
end $$;

alter table restocks enable row level security;
alter table restock_items enable row level security;
drop policy if exists team_read on restocks;
create policy team_read on restocks for select to authenticated using (is_team());
drop policy if exists team_read on restock_items;
create policy team_read on restock_items for select to authenticated using (is_team());
revoke all on restocks, restock_items from anon, authenticated;
grant select on restocks, restock_items to authenticated;
revoke execute on all functions in schema public from public, anon;
grant execute on function create_restock(jsonb, text), update_restock(uuid, jsonb, text), receive_restock(uuid, jsonb, text),
  restocks_list(boolean), stock_overview(boolean) to authenticated, service_role;
grant execute on function stock_sync(jsonb, boolean, text) to service_role;


-- ===================== 0007_assistant.sql =====================
-- Triangle Resells CRM v1: the team assistant (a chat in the CRM) and team notes for the DM bot.
-- The assistant acts AS the logged-in person (their login calls these functions), so everything it does is logged under
-- their name and can be undone like any other change.

-- Who's logged in (the assistant greets them and logs as them).
create or replace function whoami() returns text
language sql stable security definer set search_path = public as $$
  select name from team_members where user_id = auth.uid()
$$;

-- Things the team tells the DM bot ("the BAPE restock moved to Tuesday", "we're closed Thanksgiving").
-- The bot reads the active ones before every reply; they win over the knowledge base when they disagree.
create table if not exists bot_notes (
  id uuid primary key default gen_random_uuid(),
  note text not null check (length(trim(note)) between 1 and 1000),
  active boolean not null default true,
  expires_on date,                      -- optional: stops applying after this day (e.g. a holiday closure)
  created_by text not null default 'System',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

drop trigger if exists bot_notes_touch on bot_notes;
create trigger bot_notes_touch before update on bot_notes for each row execute function crm_touch();
drop trigger if exists bot_notes_log on bot_notes;
create trigger bot_notes_log after insert or update or delete on bot_notes for each row execute function crm_log_change();

create or replace function crm_undoable() returns text[] language sql immutable as $$
  select array['customers', 'bookings', 'booking_items', 'restocks', 'restock_items', 'bot_notes']
$$;

create or replace function add_bot_note(p_note text, p_expires_on date default null, p_actor text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare a text; n bot_notes;
begin
  a := crm_begin(p_actor);
  perform crm_begin(p_actor, a || ' told the bot: ' || left(trim(p_note), 120));
  insert into bot_notes (note, expires_on, created_by) values (trim(p_note), p_expires_on, a) returning * into n;
  return to_jsonb(n);
end $$;

create or replace function retire_bot_note(p_id uuid, p_actor text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare a text; n bot_notes;
begin
  a := crm_begin(p_actor);
  select * into n from bot_notes where id = p_id;
  if n.id is null then raise exception 'no note %', p_id using errcode = 'P0002'; end if;
  perform crm_begin(p_actor, a || ' retired a bot note: ' || left(n.note, 120));
  update bot_notes set active = false where id = p_id returning * into n;
  return to_jsonb(n);
end $$;

-- Active notes, newest first (expired ones drop off by themselves).
create or replace function bot_notes_active(p_today date default (now() at time zone 'America/New_York')::date) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  perform crm_team_or_service();
  return coalesce((select jsonb_agg(to_jsonb(n) order by n.created_at desc) from bot_notes n
    where n.active and (n.expires_on is null or n.expires_on >= p_today)), '[]'::jsonb);
end $$;

alter table bot_notes enable row level security;
drop policy if exists team_read on bot_notes;
create policy team_read on bot_notes for select to authenticated using (is_team());
revoke all on bot_notes from anon, authenticated;
grant select on bot_notes to authenticated;
revoke execute on all functions in schema public from public, anon;
grant execute on function whoami(), add_bot_note(text, date, text), retire_bot_note(uuid, text), bot_notes_active(date) to authenticated, service_role;


-- ===================== 0008_phase5.sql =====================
-- Triangle Resells CRM v1, phase 5: team notifications, video ideas, old sales import.

-- ======================================================================================
-- Notifications: an outbox the bot posts to the team's Discord / Slack channel.
-- The bot's own bookings, reschedules and cancels already alert (with payment instructions), so those are skipped here.
-- ======================================================================================
create table if not exists team_notifications (
  id bigserial primary key,
  at timestamptz not null default now(),
  kind text not null,                  -- booked, rescheduled, cancelled, no_show, out_of_stock, video_ideas
  text text not null,
  actor text not null,
  booking_id uuid,
  is_test boolean not null default false
);

create or replace function crm_when_text(d date, t time) returns text language sql immutable as $$
  select trim(to_char(d, 'Dy Mon FMDD') || coalesce(' ' || ltrim(to_char(t, 'FMHH12:MI AM'), '0'), ''))
$$;

create or replace function crm_booking_line(p_id uuid) returns text
language sql stable security definer set search_path = public as $$
  select concat_ws(', ',
    coalesce(nullif('@' || c.ig_handle, '@'), c.name, 'a buyer'),
    (select string_agg(i.qty || 'x ' || concat_ws(' ', i.item, i.color, case when crm_size_key(i.size) = '' then null else i.size end), ', ' order by i.created_at)
       from booking_items i where i.booking_id = b.id),
    b.fulfillment, '$' || trim(to_char(b.sale_price, 'FM999999990.00')))
  from bookings b left join customers c on c.id = b.customer_id where b.id = p_id
$$;

create or replace function crm_notify_booking() returns trigger
language plpgsql security definer set search_path = public as $$
declare a text := crm_actor(); line text; tag text := case when new.is_test then '[TEST] ' else '' end;
begin
  if a = 'Bot' then return null; end if;           -- the bot already alerted for its own changes
  -- Imported history never notifies (checked on the row: this runs at commit, after the import finished).
  if new.imported_from is not null then return null; end if;
  line := crm_booking_line(new.id);
  if line is null then return null; end if;
  if tg_op = 'INSERT' then
    if new.status not in ('cancelled', 'no_show') then
      insert into team_notifications (kind, text, actor, booking_id, is_test) values ('booked',
        tag || '📅 ' || a || ' booked a sale for ' || crm_when_text(new.date, new.time) || ': ' || line
          || '. Fulfilling: ' || coalesce(new.assignee, 'nobody yet') || '.', a, new.id, new.is_test);
    end if;
  elsif (old.date, old.time) is distinct from (new.date, new.time) and new.status not in ('cancelled', 'no_show', 'done') then
    insert into team_notifications (kind, text, actor, booking_id, is_test) values ('rescheduled',
      tag || '🔁 ' || a || ' rescheduled ' || line || ' to ' || crm_when_text(new.date, new.time) || ' (was ' || crm_when_text(old.date, old.time) || ').', a, new.id, new.is_test);
  elsif old.status <> new.status and new.status in ('cancelled', 'no_show') then
    insert into team_notifications (kind, text, actor, booking_id, is_test) values (new.status,
      tag || case new.status when 'cancelled' then '❌ ' || a || ' cancelled ' else '🚫 No-show (marked by ' || a || '): ' end
        || line || ' on ' || crm_when_text(new.date, new.time) || coalesce(' (' || new.status_reason || ')', '') || '.', a, new.id, new.is_test);
  end if;
  return null;
end $$;
drop trigger if exists bookings_notify on bookings;
create constraint trigger bookings_notify after insert or update on bookings
  deferrable initially deferred for each row execute function crm_notify_booking();

create or replace function crm_notify_stock() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.qty = 0 and old.qty > 0 and new.status = 'for_sale' then
    insert into team_notifications (kind, text, actor, is_test) values ('out_of_stock',
      case when new.is_test then '[TEST] ' else '' end || '⚠️ Out of stock: ' || concat_ws(' ', new.item, new.color, case when crm_size_key(new.size) = '' then null else new.size end)
        || '. The bot won''t sell it until it''s restocked.', crm_actor(), new.is_test);
  end if;
  return null;
end $$;
drop trigger if exists stock_items_notify on stock_items;
-- At commit too, so "out of stock" comes after the booking that sold the last piece.
create constraint trigger stock_items_notify after update of qty on stock_items
  deferrable initially deferred for each row execute function crm_notify_stock();

create or replace function notifications_after(p_after bigint, p_limit integer default 100) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if coalesce(auth.role(), '') <> 'service_role' then raise exception 'bot only' using errcode = '42501'; end if;
  if p_after is null then
    return jsonb_build_object('notifications', '[]'::jsonb, 'latest', coalesce((select max(id) from team_notifications), 0));
  end if;
  return jsonb_build_object(
    'notifications', coalesce((select jsonb_agg(to_jsonb(n) order by n.id) from (
      select * from team_notifications where id > p_after order by id limit least(greatest(p_limit, 1), 500)) n), '[]'::jsonb),
    'latest', coalesce((select max(id) from team_notifications), 0));
end $$;

-- ======================================================================================
-- Video ideas: daily, per account. Goals: Resells 3, Scales 2, Sales 6 (incl. a meetup video).
-- ======================================================================================
create table if not exists video_ideas (
  id uuid primary key default gen_random_uuid(),
  day date not null,
  account text not null check (account in ('resells', 'scales', 'sales')),
  hook text not null check (length(trim(hook)) between 1 and 300),
  meetup boolean not null default false,
  status text not null default 'todo' check (status in ('todo', 'filmed', 'posted')),
  posted_to text[] not null default '{}' check (posted_to <@ array['resells', 'scales', 'sales']),
  post_link text,
  views integer check (views >= 0),
  auto boolean not null default false,   -- generated by the bot
  sort integer not null default 0,
  created_by text not null default 'System',
  is_test boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists video_ideas_day_idx on video_ideas (day);
drop trigger if exists video_ideas_touch on video_ideas;
create trigger video_ideas_touch before update on video_ideas for each row execute function crm_touch();
drop trigger if exists video_ideas_log on video_ideas;
create trigger video_ideas_log after insert or update or delete on video_ideas for each row execute function crm_log_change();

create or replace function crm_undoable() returns text[] language sql immutable as $$
  select array['customers', 'bookings', 'booking_items', 'restocks', 'restock_items', 'bot_notes', 'video_ideas']
$$;

create or replace function video_goals() returns jsonb language sql immutable as $$
  select '{"resells": 3, "scales": 2, "sales": 6}'::jsonb
$$;

-- p_ideas: [{account, hook, meetup}]. Returns the day's ideas.
create or replace function add_video_ideas(p_day date, p_ideas jsonb, p_auto boolean default false, p_actor text default null, p_is_test boolean default false) returns jsonb
language plpgsql security definer set search_path = public as $$
declare a text; n integer;
begin
  a := crm_begin(p_actor);
  if p_ideas is null or jsonb_typeof(p_ideas) <> 'array' or jsonb_array_length(p_ideas) = 0 then
    raise exception 'no ideas given' using errcode = '22023';
  end if;
  n := jsonb_array_length(p_ideas);
  perform crm_begin(p_actor, a || ' added ' || n || ' video idea' || case when n = 1 then '' else 's' end || ' for ' || p_day);
  insert into video_ideas (day, account, hook, meetup, auto, sort, created_by, is_test)
  select p_day, i ->> 'account', trim(i ->> 'hook'), coalesce((i ->> 'meetup')::boolean, false), p_auto,
         coalesce((select max(sort) from video_ideas where day = p_day), 0) + ord::integer, a, p_is_test
  from jsonb_array_elements(p_ideas) with ordinality as x(i, ord);
  if p_auto and n > 0 then
    insert into team_notifications (kind, text, actor, is_test) values ('video_ideas',
      case when p_is_test then '[TEST] ' else '' end || '🎬 ' || n || ' new video idea' || case when n = 1 then '' else 's' end
        || ' for ' || crm_when_text(p_day, null) || ' are in the CRM.', a, p_is_test);
  end if;
  return videos_for_day(p_day, p_is_test);
end $$;

-- p: {hook, status, posted_to, post_link, views, account, meetup}
create or replace function update_video_idea(p_id uuid, p jsonb, p_actor text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare a text; v video_ideas;
begin
  a := crm_begin(p_actor);
  select * into v from video_ideas where id = p_id for update;
  if v.id is null then raise exception 'no video idea %', p_id using errcode = 'P0002'; end if;
  perform crm_begin(p_actor, a || ' updated a video idea: ' || left(v.hook, 80));
  update video_ideas set
    hook = coalesce(nullif(trim(p ->> 'hook'), ''), hook),
    status = coalesce(nullif(p ->> 'status', ''), status),
    account = coalesce(nullif(p ->> 'account', ''), account),
    meetup = coalesce((p ->> 'meetup')::boolean, meetup),
    posted_to = case when p ? 'posted_to' then array(select jsonb_array_elements_text(p -> 'posted_to')) else posted_to end,
    post_link = case when p ? 'post_link' then nullif(trim(p ->> 'post_link'), '') else post_link end,
    views = case when p ? 'views' then (p ->> 'views')::integer else views end
  where id = p_id returning * into v;
  return to_jsonb(v);
end $$;

create or replace function delete_video_idea(p_id uuid, p_actor text default null) returns void
language plpgsql security definer set search_path = public as $$
declare a text;
begin
  a := crm_begin(p_actor, null);
  perform crm_begin(p_actor, a || ' removed a video idea');
  delete from video_ideas where id = p_id;
end $$;

create or replace function videos_for_day(p_day date, p_is_test boolean default false) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  perform crm_team_or_service();
  return jsonb_build_object('day', p_day, 'goals', video_goals(),
    'ideas', coalesce((select jsonb_agg(to_jsonb(v) order by v.account, v.sort, v.created_at) from video_ideas v where v.day = p_day and v.is_test = p_is_test), '[]'::jsonb));
end $$;

-- For the calendar: per day, how many ideas and how many posted.
create or replace function videos_between(p_from date, p_to date, p_is_test boolean default false) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  perform crm_team_or_service();
  return coalesce((select jsonb_object_agg(day, jsonb_build_object('ideas', n, 'posted', p)) from (
    select day, count(*) n, count(*) filter (where status = 'posted') p from video_ideas
     where day between p_from and p_to and is_test = p_is_test group by day) x), '{}'::jsonb);
end $$;

-- Recent hooks (so new ones don't repeat them).
create or replace function recent_hooks(p_days integer default 30) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  perform crm_team_or_service();
  return coalesce((select jsonb_agg(hook order by created_at desc) from (
    select hook, created_at from video_ideas where created_at > now() - make_interval(days => p_days) and not is_test order by created_at desc limit 200) x), '[]'::jsonb);
end $$;

-- ======================================================================================
-- Profit also takes off other costs (e.g. a platform fee on old online sales).
-- ======================================================================================
alter table bookings add column if not exists other_costs numeric(10, 2) not null default 0 check (other_costs >= 0);
alter table bookings add column if not exists imported_from text;   -- "Nov 2026!A12": where an imported sale came from
create unique index if not exists bookings_imported_from_key on bookings (imported_from) where imported_from is not null;

create or replace function crm_sale_row(b bookings) returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'id', b.id, 'date', b.date, 'time', b.time, 'status', b.status,
    'customer', (select jsonb_build_object('id', c.id, 'ig_handle', c.ig_handle, 'name', c.name, 'phone', c.phone) from customers c where c.id = b.customer_id),
    'items', coalesce((select jsonb_agg(jsonb_build_object('brand', i.brand, 'item', i.item, 'color', i.color, 'size', i.size, 'qty', i.qty,
        'unit_price', i.unit_price, 'unit_cost', i.unit_cost) order by i.created_at, i.id) from booking_items i where i.booking_id = b.id), '[]'::jsonb),
    'revenue', b.sale_price,
    'item_cost', coalesce((select sum(i.qty * i.unit_cost) from booking_items i where i.booking_id = b.id), 0),
    'label_cost', b.label_cost + b.other_costs,
    'cost_missing', exists (select 1 from booking_items i where i.booking_id = b.id and i.unit_cost is null),
    'profit', b.sale_price - coalesce((select sum(i.qty * i.unit_cost) from booking_items i where i.booking_id = b.id), 0) - b.label_cost - b.other_costs,
    'delivery_fee', b.delivery_fee, 'shipping_fee', b.shipping_fee,
    'payment_method', b.payment_method, 'fulfillment', b.fulfillment, 'location', b.location,
    'assignee', b.assignee, 'source', b.source, 'source_account', b.source_account, 'tracking_number', b.tracking_number,
    'cash_collected_by', b.cash_collected_by, 'imported', b.imported_from is not null, 'is_test', b.is_test)
$$;

create or replace function monthly_report(p_months integer default 12, p_filters jsonb default '{}', p_include_test boolean default false,
                                          p_today date default (now() at time zone 'America/New_York')::date) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  perform crm_team_or_service();
  return (select jsonb_agg(jsonb_build_object('month', to_char(m, 'YYYY-MM'),
      'revenue', coalesce(x.rev, 0), 'profit', coalesce(x.prof, 0), 'sales', coalesce(x.n, 0), 'open', coalesce(o.open, 0)) order by m)
    from generate_series(date_trunc('month', p_today) - make_interval(months => least(greatest(p_months, 1), 60) - 1), date_trunc('month', p_today), interval '1 month') m
    left join (
      select date_trunc('month', b.date) mon, sum(b.sale_price) rev,
             sum(b.sale_price - coalesce((select sum(i.qty * i.unit_cost) from booking_items i where i.booking_id = b.id), 0) - b.label_cost - b.other_costs) prof, count(*) n
        from bookings b where b.status = 'done' and (p_include_test or not b.is_test) and crm_sale_matches(b, coalesce(p_filters, '{}'))
       group by 1) x on x.mon = m
    left join (
      select date_trunc('month', b.date) mon, sum(b.sale_price) open
        from bookings b where b.status in ('booked', 'paid', 'paid_needs_check') and (p_include_test or not b.is_test) and crm_sale_matches(b, coalesce(p_filters, '{}'))
       group by 1) o on o.mon = m);
end $$;

-- ======================================================================================
-- Old sales import (from the sales tracker). Historical: Done, no stock reserved, no notifications.
-- p_rows: [{key, date, channel, handle, buyer_name, phone, products, cost, total, platform_fee, label_cost, payment, closer,
--           fulfillment, location, tracking, notes, items: [{item, color, size, qty}]}]
-- p_commit = false: a preview, nothing written. true: writes the rows not imported before.
-- ======================================================================================
create or replace function crm_import_payment(p text) returns text language sql immutable as $$
  select case
    when lower(coalesce(p, '')) ~ 'cash ?app' then 'cash_app'
    when lower(coalesce(p, '')) ~ 'zelle' then 'zelle'
    when lower(coalesce(p, '')) ~ 'apple' then 'apple_pay'
    when lower(coalesce(p, '')) ~ 'stripe|card|shopify' then 'stripe'
    else 'cash' end
$$;

create or replace function import_sales(p_rows jsonb, p_commit boolean default false, p_actor text default 'System') returns jsonb
language plpgsql security definer set search_path = public as $$
declare r jsonb; it jsonb; cust jsonb; bid uuid; pay text; ful text; total numeric; cost numeric; pieces integer; added integer := 0; skipped integer := 0; problems jsonb := '[]';
begin
  if coalesce(auth.role(), '') <> 'service_role' then raise exception 'bot only' using errcode = '42501'; end if;
  if jsonb_typeof(p_rows) <> 'array' then raise exception 'rows must be a list' using errcode = '22023'; end if;
  perform crm_begin(p_actor, 'Imported an old sale from the sales tracker');
  perform set_config('crm.importing', 'on', true);
  for r in select * from jsonb_array_elements(p_rows) loop
    if nullif(r ->> 'date', '') is null or nullif(r ->> 'total', '') is null then
      problems := problems || jsonb_build_object('key', r ->> 'key', 'problem', 'no date or no total');
      continue;
    end if;
    if exists (select 1 from bookings where imported_from = r ->> 'key') then skipped := skipped + 1; continue; end if;
    if not p_commit then added := added + 1; continue; end if;
    pay := crm_import_payment(r ->> 'payment');
    ful := coalesce(nullif(r ->> 'fulfillment', ''), 'pickup');
    if pay = 'cash' and ful <> 'pickup' then pay := 'cash_app'; end if;   -- old rows: cash can't be "shipped"; keep the sale
    total := (r ->> 'total')::numeric;
    cost := nullif(r ->> 'cost', '')::numeric;
    if nullif(r ->> 'handle', '') is not null or nullif(r ->> 'buyer_name', '') is not null or nullif(r ->> 'phone', '') is not null then
      cust := upsert_customer(jsonb_build_object('ig_handle', r ->> 'handle', 'name', r ->> 'buyer_name', 'phone', r ->> 'phone'), p_actor);
      perform set_config('crm.importing', 'on', true);
    else
      cust := null;
    end if;
    insert into bookings (date, customer_id, status, payment_method, fulfillment, sale_price, label_cost, other_costs, location,
                          assignee, source, tracking_number, notes, created_by, imported_from)
    values ((r ->> 'date')::date, (cust ->> 'id')::uuid, 'done', pay, ful, total,
            coalesce(nullif(r ->> 'label_cost', '')::numeric, 0), coalesce(nullif(r ->> 'platform_fee', '')::numeric, 0),
            nullif(r ->> 'location', ''), case when r ->> 'closer' in ('Josh', 'Chema', 'Diego') then r ->> 'closer' end,
            case when lower(coalesce(r ->> 'channel', '')) ~ 'insta|ig' then 'instagram' when lower(coalesce(r ->> 'channel', '')) ~ 'text' then 'text'
                 when lower(coalesce(r ->> 'channel', '')) ~ 'refer' then 'referral' when ful = 'pickup' then 'in_person' else 'other' end,
            case when ful = 'ship' then nullif(r ->> 'tracking', '') end,
            concat_ws(' · ', 'Imported from ' || (r ->> 'key'), nullif(r ->> 'products', ''), nullif(r ->> 'notes', '')),
            p_actor, r ->> 'key')
    returning id into bid;
    -- Lines: the parsed items, or one line with the whole "Products Sold" text. Cost is spread so the total matches the sheet.
    pieces := coalesce((select sum(greatest(coalesce((x ->> 'qty')::integer, 1), 1)) from jsonb_array_elements(coalesce(r -> 'items', '[]')) x), 0);
    if pieces = 0 then
      insert into booking_items (booking_id, item, size, qty, unit_price, unit_cost, reserved)
      values (bid, coalesce(nullif(left(r ->> 'products', 200), ''), 'Old sale'), 'One Size', 1, total, cost, false);
    else
      for it in select * from jsonb_array_elements(r -> 'items') loop
        insert into booking_items (booking_id, item, color, size, qty, unit_price, unit_cost, reserved)
        values (bid, it ->> 'item', nullif(it ->> 'color', ''), coalesce(nullif(it ->> 'size', ''), 'One Size'), greatest(coalesce((it ->> 'qty')::integer, 1), 1),
                round(total / pieces, 2), case when cost is null then null else round(cost / pieces, 2) end, false);
      end loop;
    end if;
    added := added + 1;
  end loop;
  perform set_config('crm.importing', '', true);
  return jsonb_build_object('committed', p_commit, (case when p_commit then 'imported' else 'would_import' end), added,
    'already_imported', skipped, 'problems', problems);
end $$;

-- Imports never reserve stock (they're history).
create or replace function crm_reserve_line() returns trigger
language plpgsql security definer set search_path = public as $$
declare s stock_items; st text;
begin
  if current_setting('crm.importing', true) = 'on' then return new; end if;
  select status into st from bookings where id = new.booking_id;
  if st is null or not crm_booking_open(st) then return new; end if;
  s := crm_find_stock(new.item, new.color, new.size, new.is_test);
  if s.id is null then
    raise exception '% isn''t a FOR SALE item on BOT STOCK%', crm_line_name(new),
      case when new.is_test then ' (TEST stock)' else '' end using errcode = '22023';
  end if;
  if s.qty < new.qty then
    raise exception 'only % left of % (asked for %)', s.qty, crm_line_name(new), new.qty using errcode = 'TR409';
  end if;
  perform crm_stock_move(s.id, -new.qty, 'booked', new.booking_id);
  new.stock_item_id := s.id;
  new.reserved := true;
  if new.unit_cost is null then new.unit_cost := s.cost; end if;
  return new;
end $$;

-- Imported cash sales aren't "cash collected today".
create or replace function crm_cash_collect() returns trigger
language plpgsql security definer set search_path = public as $$
declare a text := crm_actor();
begin
  if current_setting('crm.importing', true) = 'on' then return new; end if;
  if tg_op = 'INSERT' then
    if new.payment_method = 'cash' and new.status in ('paid', 'done') then
      new.cash_collected_at := now();
      new.cash_collected_by := coalesce(new.cash_collected_by, case when a in ('Josh', 'Chema', 'Diego') then a end, new.assignee);
    end if;
    return new;
  end if;
  if new.payment_method = 'cash' and new.status in ('paid', 'done') and new.cash_collected_at is null then
    new.cash_collected_at := now();
    new.cash_collected_by := coalesce(new.cash_collected_by, case when a in ('Josh', 'Chema', 'Diego') then a end, new.assignee);
  elsif new.status not in ('paid', 'done') and old.status in ('paid', 'done') and new.payment_method = 'cash' then
    new.cash_collected_at := null;
    new.cash_collected_by := null;
  end if;
  return new;
end $$;

alter table team_notifications enable row level security;
alter table video_ideas enable row level security;
drop policy if exists team_read on team_notifications;
create policy team_read on team_notifications for select to authenticated using (is_team());
drop policy if exists team_read on video_ideas;
create policy team_read on video_ideas for select to authenticated using (is_team());
revoke all on team_notifications, video_ideas from anon, authenticated;
grant select on team_notifications, video_ideas to authenticated;
revoke execute on all functions in schema public from public, anon;
grant execute on function notifications_after(bigint, integer), import_sales(jsonb, boolean, text) to service_role;
grant execute on function add_video_ideas(date, jsonb, boolean, text, boolean), update_video_idea(uuid, jsonb, text), delete_video_idea(uuid, text),
  videos_for_day(date, boolean), videos_between(date, date, boolean), recent_hooks(integer) to authenticated, service_role;

do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    begin
      alter publication supabase_realtime add table video_ideas;
    exception when duplicate_object then null;
    end;
  end if;
end $$;


-- ===================== 0009_test_cleanup.sql =====================
-- Triangle Resells CRM v1: delete all TEST data after the end-to-end tests (the brief: "After tests: delete all test
-- data"). Only rows marked is_test go; real bookings, customers, stock and history are never touched. Bot only.

create or replace function delete_test_data(p_actor text default 'System') returns jsonb
language plpgsql security definer set search_path = public as $$
declare n_bookings integer; n_restocks integer; n_videos integer; n_customers integer; n_stock integer;
begin
  if coalesce(auth.role(), '') <> 'service_role' then raise exception 'bot only' using errcode = '42501'; end if;
  perform crm_begin(p_actor, 'Deleted TEST data');
  -- Bookings first: their lines give TEST stock back on the way out (TEST stock only), then go with them.
  with d as (delete from bookings where is_test returning 1) select count(*) into n_bookings from d;
  with d as (delete from restocks where is_test returning 1) select count(*) into n_restocks from d;
  with d as (delete from video_ideas where is_test returning 1) select count(*) into n_videos from d;
  -- TEST customers that no real booking points to.
  with d as (delete from customers c where c.is_test and not exists (select 1 from bookings b where b.customer_id = c.id) returning 1)
    select count(*) into n_customers from d;
  delete from bot_events where is_test;
  delete from team_notifications where is_test;
  delete from stock_moves where is_test;
  with d as (delete from stock_items s where s.is_test
                and not exists (select 1 from booking_items i where i.stock_item_id = s.id)
                and not exists (select 1 from restock_items r where r.stock_item_id = s.id) returning 1)
    select count(*) into n_stock from d;
  -- The log lines about test rows (including the ones these deletes just wrote) go last.
  delete from activity_log where is_test;
  return jsonb_build_object('bookings', n_bookings, 'restocks', n_restocks, 'video_ideas', n_videos, 'customers', n_customers, 'test_stock_rows', n_stock);
end $$;

revoke execute on all functions in schema public from public, anon;
grant execute on function delete_test_data(text) to service_role;
